import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Chunk Certificates","description":"","frontmatter":{"title":"Chunk Certificates","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — deferred until untrusted chunk sources are a real concern.\\n\\nDepends on [ADR-0066 — Dependency-Graph Chunking](./0066-dependency-graph-chunking.md)\\n(chunks are the unit being certified) and\\n[ADR-0065 — Derived-Artifact Cache and Compression](./0065-derived-artifact-cache-and-compression.md)\\n(cached artifacts are the trust targets). Refines\\n[ADR-0046 — Capability Discipline at the Language Level](./0046-capability-discipline-at-the-language-level.md)\\n(static capability verification) and\\n[ADR-0044 — Language as Data and Runtime Split](./0044-language-as-data-and-runtime-split.md)\\n(`Language` as serializable data)."},"headers":[],"relativePath":"handl/project/adrs/0067-chunk-certificates.md","filePath":"vendored/handl/project/adrs/0067-chunk-certificates.md"}'),a={name:`handl/project/adrs/0067-chunk-certificates.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0067-chunk-certificates" tabindex="-1">ADR-0067: Chunk Certificates <a class="header-anchor" href="#adr-0067-chunk-certificates" aria-label="Permalink to “ADR-0067: Chunk Certificates”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-a-certificate-is-a-signed-statement-about-a-chunk" tabindex="-1">1. A certificate is a signed statement about a chunk <a class="header-anchor" href="#_1-a-certificate-is-a-signed-statement-about-a-chunk" aria-label="Permalink to “1. A certificate is a signed statement about a chunk”">​</a></h3><p>A certificate is a detached signature over a canonical serialization of:</p><ul><li>The chunk&#39;s content hash (BLAKE3, per ADR-0065 §2).</li><li>The chunk&#39;s dependencies (chunk ids + content hashes, per ADR-0066 §2).</li><li>The chunk&#39;s declared capability set (per ADR-0046 §1 <code>CapabilitySet</code>).</li><li>The chunk&#39;s <code>replaces</code> targets (per ADR-0044 §5, ADR-0066 §2).</li><li>The chunk&#39;s <code>scheme_version</code> (per ADR-0044 §7).</li><li>Metadata: author id, timestamp, certificate version.</li></ul><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Certificate = {</span></span>
<span class="line"><span>    chunk_hash: Blake3,</span></span>
<span class="line"><span>    dependencies: Map&lt;ChunkId, Blake3&gt;,</span></span>
<span class="line"><span>    capabilities: CapabilitySet,</span></span>
<span class="line"><span>    replaces: Map&lt;FragmentId, ChunkId&gt;,</span></span>
<span class="line"><span>    scheme_version: String,</span></span>
<span class="line"><span>    author: AuthorId,</span></span>
<span class="line"><span>    timestamp: u64,</span></span>
<span class="line"><span>    cert_version: u32,</span></span>
<span class="line"><span>    signature: Signature,  // over canonical_serialize of all above fields</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The signature is Ed25519. The author&#39;s public key is distributed out of band (key server, pinned in host config, or Web-of-Trust).</p><h3 id="_2-verification-happens-before-load-not-after" tabindex="-1">2. Verification happens before load, not after <a class="header-anchor" href="#_2-verification-happens-before-load-not-after" aria-label="Permalink to “2. Verification happens before load, not after”">​</a></h3><p>A chunk is verified <strong>before</strong> it is loaded into memory. The runtime:</p><ol><li>Reads the chunk and its certificate.</li><li>Recomputes the chunk&#39;s content hash; verifies it matches the certificate.</li><li>Verifies the signature against the author&#39;s public key.</li><li>Checks the author is in the host&#39;s trust store.</li><li>Checks the declared capability set against the host&#39;s policy (ADR-0046 §3).</li><li>Recursively verifies each dependency chunk&#39;s certificate.</li></ol><p>If any step fails, the chunk is rejected. It is not loaded, not decompressed, not typechecked. This is defense-in-depth: ADR-0046&#39;s capability check inspects the data; this ADR&#39;s certificate verifies the data hasn&#39;t been tampered with and comes from a trusted source.</p><h3 id="_3-dependency-certificates-are-required" tabindex="-1">3. Dependency certificates are required <a class="header-anchor" href="#_3-dependency-certificates-are-required" aria-label="Permalink to “3. Dependency certificates are required”">​</a></h3><p>A chunk&#39;s certificate includes its dependencies&#39; content hashes (ADR-0066 §2). When loading a chunk, the runtime verifies that each dependency&#39;s actual content hash matches the hash in the certificate. This prevents supply-chain substitution: a dependency chunk with the same id but different content fails verification.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>for dep_id, expected_hash in cert.dependencies:</span></span>
<span class="line"><span>    dep_chunk = load(dep_id)</span></span>
<span class="line"><span>    assert(blake3(dep_chunk) == expected_hash)</span></span>
<span class="line"><span>    verify_certificate(dep_chunk)</span></span></code></pre></div><p>This is recursive: a chunk is only trusted if its entire transitive dependency closure is trusted.</p><h3 id="_4-trust-store-is-a-host-config-not-a-language-property" tabindex="-1">4. Trust store is a host config, not a language property <a class="header-anchor" href="#_4-trust-store-is-a-host-config-not-a-language-property" aria-label="Permalink to “4. Trust store is a host config, not a language property”">​</a></h3><p>The set of trusted authors (public keys) is a host-level configuration, not part of the <code>Language</code> data. A <code>Language</code> does not declare who is allowed to author it; the host decides what to trust. This keeps trust out of the data model (ADR-0044: <code>Language</code> is pure data, no policy) and in the host&#39;s control (ADR-0046: the host attaches policies at registration time).</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># host config</span></span>
<span class="line"><span>[trust]</span></span>
<span class="line"><span>trusted_authors = [&quot;ed25519:abc123...&quot;, &quot;ed25519:def456...&quot;]</span></span></code></pre></div><h3 id="_5-revocation-via-a-revocation-list" tabindex="-1">5. Revocation via a revocation list <a class="header-anchor" href="#_5-revocation-via-a-revocation-list" aria-label="Permalink to “5. Revocation via a revocation list”">​</a></h3><p>A certificate can be revoked before its natural expiry. The host maintains a revocation list (chunk hashes or author ids that are no longer trusted). A chunk whose certificate is on the revocation list is rejected, even if the signature is valid.</p><p>The revocation list is a host config, updated out of band (e.g., fetched from a key server periodically). This is the standard PKI pattern; no novel design here.</p><h3 id="_6-certificates-are-optional-per-chunk" tabindex="-1">6. Certificates are optional per-chunk <a class="header-anchor" href="#_6-certificates-are-optional-per-chunk" aria-label="Permalink to “6. Certificates are optional per-chunk”">​</a></h3><p>Not every chunk needs a certificate. A chunk from a trusted local source (in-repo, compile-time-embedded) does not need one. A chunk from an untrusted source (third-party mod, network load, shared cache) does.</p><p>The runtime config specifies the policy:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">[</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">certificates</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">required </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">always</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFAA80;--shiki-dark-text-decoration:underline;--shiki-dark-font-style:inherit;--shiki-light:#B31D28;--shiki-light-text-decoration:inherit;--shiki-light-font-style:italic;"> | &quot;untrusted-only&quot; | &quot;never&quot;</span></span></code></pre></div><ul><li><code>always</code> — every chunk must have a valid certificate (strictest).</li><li><code>untrusted-only</code> — chunks from trusted sources (local, compile-time) skip verification; chunks from untrusted sources (network, third-party) require it.</li><li><code>never</code> — no verification (default today; equivalent to no certificate subsystem).</li></ul><h3 id="_7-capability-set-in-the-certificate-is-a-claim-verified-by-adr-0046" tabindex="-1">7. Capability set in the certificate is a claim, verified by ADR-0046 <a class="header-anchor" href="#_7-capability-set-in-the-certificate-is-a-claim-verified-by-adr-0046" aria-label="Permalink to “7. Capability set in the certificate is a claim, verified by ADR-0046”">​</a></h3><p>The certificate includes the chunk&#39;s declared <code>CapabilitySet</code> (ADR-0046 §1). This is a <strong>claim</strong> by the author. The runtime verifies the claim by computing the <code>CapabilitySet</code> from the chunk&#39;s data (ADR-0046 §1 <code>CapabilitySet::from_language</code>) and comparing. A mismatch — the certificate claims <code>fs-write</code> is not used, but the data contains a <code>Foreign(&quot;fs-write&quot;)</code> scheme — is a verification failure. The chunk is rejected.</p><p>This closes the tampering gap: an attacker cannot modify the chunk to add a <code>Foreign</code> scheme without invalidating the signature, and cannot lie about the capability set without the runtime detecting the mismatch.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0065 (cache/compression) and ADR-0066 (chunking) are optimization techniques. This ADR is a different concern: <strong>trust</strong>. It answers &quot;do I believe this chunk is what its author claims it is, and does it come from a source I trust?&quot;</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Provenance and integrity, not just declared capabilities.</strong> ADR-0046</li><li><strong>Per-chunk trust.</strong> A new chunk from a trusted author is certified</li><li><strong>Supply-chain substitution is detected.</strong> A dependency chunk with the</li><li><strong>Capability-set tampering is detected.</strong> The certificate&#39;s declared</li><li><strong>Cryptographic overhead on every load of a certified chunk.</strong> Ed25519</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0067-chunk-certificates.html"><code>design/0067-chunk-certificates.md</code></a>.</p>`,39)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};